"""Bind quoted-label repair claims to actual retained producers and all artifacts."""
from pathlib import Path
import hashlib
import json

ROOT = Path(__file__).resolve().parents[2]
OWNER = 'SPEC-LANGUAGE-SELF-CONTAINMENT.1.3.3.0.7.2.2.0.1.4.0.1'
PREFIX = 'docs/checkpoints/'+OWNER+'-'
REVISION = 'da5c8d1f66732f0989cecca745557005fe44e7c1'


def sha(path):
    return hashlib.sha256((ROOT/path).read_bytes()).hexdigest()


runtime, book, freeze = [json.loads((ROOT/(PREFIX+name+'.json')).read_bytes()) for name in ('verification', 'book-verification', 'freeze')]
assert runtime['complete'] and book['complete'] and runtime['revision'] == freeze['revision'] == REVISION
assert (runtime['cases'], runtime['compiler_cases'], runtime['runtime_successes'], runtime['events_per_seed'], runtime['seeds'], runtime['commands'], runtime['before_red_groups'], runtime['after_green_groups'], runtime['fixture_suites'], runtime['fixture_groups']) == (18,14,13,28,3,8,9,18,9,1169)
assert runtime['runtime_exclusion'] == OWNER+'.1'
assert len(runtime['controls']) == 36 and all(c['observed'] == 'RED' and c['reason'] for c in runtime['controls'])
assert (book['book_inputs'], book['rendered_examples'], book['rendered_sections'], len(book['controls']), freeze['bound_inputs'], freeze['unique_inputs']) == (58,2,3,9,37,37)
for result, producer in ((runtime, 'review.py'), (book, 'book.py'), (freeze, 'freeze.py')):
    assert result['instrument_sha256'] == sha(PREFIX+producer)
count = runtime['regular_inputs']
statement = f'Both Perl boundary scanner and lowerer preserve complete quoted atoms through one shared private decoder, with their original outer grammar/raw calls and quote/backslash/empty-label behavior. {count} original regular Git inputs, three new before overlays and four after overlays/two exact owner replacements support eight guarded commands.18 literal cases retain28 events per seed under three seeds;14 compiler cases retain scanner/substitution/descriptor/parser-source/runtime channels. Original RED9 becomes GREEN18; nine focused suites pass1169 top-level groups including Phase01034.13 runtime cases succeed; the nested unknown-escape case remains an explicitly observed P1 exclusion with two skipped runtime assertions.36 distinguishing evidence controls and nine rendered-book controls observe RED. Complete58-input book renders two examples/three sections;37 prior claim inputs verify before historical freeze.'
scope = 'Existing Perl quoted-or-bare boundary helper contract at clean '+REVISION+'. Independent literal labels/raw calls/cumulative Unicode-CRLF repeated scalar intervals and runtime values establish the delimiter correction without new rule-definition syntax or general CSV admission. Source delta whitelist preserves all bytes outside the exact two original decode loops and shared imports; shared function matching preserves caller regex scope. Public boundary event schema remains unchanged; no provenance sidecars are added. Before/after public channels differ only in whole-label metadata/emission and three diagnosed phantom-boundary runtime values. Dynamic trace timestamps are retained but excluded from seed equality; the escaped-comma assignment trace is independently required to show actual normalization/source_span_missing. Its full parser remains unresolved and is scheduled as P1 '+OWNER+'.1 immediately after this commit, before anonymous capture. Two runtime fixture assertions explicitly skip only that owner; scanner/direct substitution remain tested. Other backends escape parity, zero-argument behavior, executable membership, remaining Legacy families and historical global audit are unassessed/separately owned. Full regular Git snapshots are a conservative parent-owned input population, not minimal observed IO; Gitlink/nonregular metadata exclude payload reads. Published dependencies and read-only host OS/Perl/Python/prove/mdBook remain execution prerequisites; all project data remains on repository volume. No dependency internals, other repositories, pins, CI/hooks or storage mechanisms change. Focused proof does not claim canonical CI; family .1.4.7 and push retain canonical boundaries.'
paths = [p.relative_to(ROOT).as_posix() for p in (ROOT/'docs/checkpoints').glob(OWNER+'-*') if p.is_file()]
paths += ['docs/checkpoints/SPEC-LANGUAGE-SELF-CONTAINMENT.1.3.3.0.7.2.2.0.1.1.1.0-capture.py', 'perl/LinkedSpec/ActionIR/Scanner/LegacyRules.pm', 'perl/LinkedSpec/ActionIR/Contracts.pm', 'perl/LinkedSpec/ActionIR/BoundaryLabels.pm', 't/capture_boundary_quoted_labels.t', 'docs/knowledge/perl-quoted-boundary-labels.md', 'docs/knowledge/perl-legacy-call-source-origins.md', 'docs/knowledge/perl-legacy-source-producer-partition.md', 'docs/linkedspec-book/src/dsl/source-boundary-helper-reference.md', 'docs/linkedspec-book/src/appendix/helper-contract-catalog.md', 'docs/linkedspec-book/src/dsl/actionir-lowering-mental-model.md', 'tools/project_data_env.sh', 'tools/project_data_run.sh', 'tools/run_python_project_data.sh', 'tools/check_claim_verification.py']
inputs = [dict(path=path, sha256=sha(path), role='producer' if path.endswith(('.py','.pl','.pm','.t','.sh')) else 'input') for path in sorted(set(paths))]
record = dict(version=1, owner=OWNER, claims=[dict(name='quoted-boundary-atom-repair', statement=statement, scope=scope,
    rederive=dict(status='checked', command='; '.join('bash tools/run_python_project_data.sh '+PREFIX+command for command in ('capture.py before','capture.py after','review.py','freeze.py','book.py --review','claim.py')), granularity=f'{count} originals/18 literal cases/28 events/14 compiler cases/13 successful runtimes plus one owned exclusion/three seeds/eight commands/1169 fixture groups/58 book inputs/37 prior hashes', result=statement),
    falsify=dict(status='checked', hypothesis='Comma fragments could resolve phantom rules; absent emitted/descriptor labels, omitted cases/inputs/channels/positive TAP, hidden nested failures or silently accepted unknown escapes could produce false acceptance.', oracle='Independent authored whole-label/cumulative original interval and runtime cursor expectations; exact retained original fragments; public generated label emission; original input object/content/mode/population; full actual channels/exits/guards/TAP and scoped source-span-missing trace; exact original source-delta whitelist.', red_control='Actual original RED9/repaired GREEN18.36 reason-specific controls fragment every14 accepted event populations, restore all three phantom runtime outcomes, hide actual source-span root, omit case/command/guard/input/module overlay, forge content/producer/channel/exit or helper descriptors/public emission/compiler tails/TAP reach/nested success and alter original owner source. Nine actual render controls reject omitted examples/contracts/limits/mechanism and forged render producers/channels/guards/exits.'),
    durability=dict(status='checked', mode='live', inputs=inputs))])
(ROOT/('docs/claims/'+OWNER+'.json')).write_text(json.dumps(record,indent=2)+'\n')
print(str(len(inputs))+' actual producer/artifact bindings; quoted boundary repair claim published with explicit nested runtime exclusion')
